/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.store.ObsSpan;

class PerformanceDetectorUnitTest {

  private static List<ObsSpan> trace(final String traceId, final int queries,
      final double serverMs) {
    List<ObsSpan> spans = new ArrayList<>();
    spans.add(new ObsSpan(0, "api", traceId, "root", "", "GET /orders", "SERVER", serverMs, "UNSET",
        Map.of("http.route", "/orders"), "1.0", "prod"));
    for (int i = 0; i < queries; i++) {
      spans.add(new ObsSpan(i, "api", traceId, "q" + i, "root", "SELECT shop.items", "CLIENT", 12,
          "UNSET", Map.of("db.system", "mariadb", "db.statement",
              "SELECT * FROM items WHERE order_id = " + (100 + i)),
          "1.0", "prod"));
    }
    return spans;
  }

  @Test
  @DisplayName("The literals of a statement are normalized")
  void normalize() {
    Assertions.assertEquals("SELECT * FROM t WHERE a = ? AND b IN (?) AND c = ?",
        PerformanceDetector
            .normalize("SELECT  * FROM t WHERE a = 12 AND b IN (1, 2, 3) AND c = 'x''y'"));
  }

  @Test
  @DisplayName("Repeated queries under one parent are an N+1; the same in another trace has the same fingerprint")
  void nPlusOne() {
    List<ErrorEvent> first = PerformanceDetector.detect(trace("t1", 20, 300), 10, 100, 0);
    List<ErrorEvent> second = PerformanceDetector.detect(trace("t2", 15, 300), 10, 100, 0);
    Assertions.assertEquals(1, first.size());
    Assertions.assertEquals(PerformanceDetector.N_PLUS_ONE, first.get(0).type());
    Assertions.assertTrue(first.get(0).message().contains("/orders"));
    Assertions.assertEquals(first.get(0).fingerprint(), second.get(0).fingerprint());
    Assertions.assertTrue(PerformanceDetector.detect(trace("t3", 5, 300), 10, 100, 0).isEmpty());
  }

  @Test
  @DisplayName("A SERVER span above the threshold is a slow operation; 0 disables it")
  void slow() {
    Assertions.assertEquals(1,
        PerformanceDetector.detect(trace("t1", 0, 8000), 10, 100, 5000).size());
    Assertions.assertTrue(PerformanceDetector.detect(trace("t1", 0, 8000), 10, 100, 0).isEmpty());
  }
}
